name: Run tests on label

on:
  pull_request:
    types: [labeled]

permissions:
  contents: read
  pull-requests: read
  actions: read

jobs:
  run-tests:
    if: github.event.label.name == 'run-tests'
    runs-on: ubuntu-latest
    steps:
      - name: Check if actor is a maintainer
        id: check
        uses: actions/github-script@v6
        with:
          script: |
            const actor = context.actor;
            const org = context.repo.owner;
            try {
              const { status } = await github.request('GET /orgs/{org}/members/{username}', {
                org,
                username: actor
              });
              if (status === 204) {
                core.setOutput('run', 'true');
              } else {
                core.setOutput('run', 'false');
              }
            } catch (error) {
              core.setOutput('run', 'false');
            }

      - name: Checkout repository
        if: steps.check.outputs.run == 'true'
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Set up Node.js
        if: steps.check.outputs.run == 'true'
        uses: actions/setup-node@v4
        with:
          node-version: '20'
          cache: 'npm'

      - name: Install dependencies
        if: steps.check.outputs.run == 'true'
        run: npm ci

      - name: Run tests
        if: steps.check.outputs.run == 'true'
        run: npm test
